//! Shared engine: one long-lived micro-VM running `docker:dind`.
//!
//! The engine is an ordinary container flagged `engine` (the guest init loads
//! bridge/netfilter modules, enables forwarding and, with a GPU, writes the
//! `veynodevm.dev/gpu` CDI spec). dockerd's TLS endpoint (mutual TLS, client
//! certificates generated by dind into a host-shared directory) is published
//! on host loopback, and a `veynodevm` docker context points at it, so the
//! stock docker CLI and compose work unchanged. Directories given with
//! `--share` are mounted at the same path, so host bind mounts under them work.
//
//! The engine itself is the daemon's (`engine.*`); this is the docker side.
use crate::{api_call, api_stream};
use anyhow::{bail, Context, Result};
use serde_json::{json, Value};
use std::{
    path::PathBuf,
    process::Command,
    time::{Duration, Instant},
};

pub const NAME: &str = "veynodevm-engine";
pub const CONTEXT: &str = "veynodevm";

fn docker_cli() -> Option<PathBuf> {
    crate::home::which("docker")
}

/// Environment for the docker CLI to reach the engine directly.
pub fn env() -> Result<Vec<(String, String)>> {
    Ok(env_of(&api_call("engine.status", json!({}))?))
}

fn env_of(status: &Value) -> Vec<(String, String)> {
    status["env"]
        .as_object()
        .into_iter()
        .flatten()
        .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_owned()))
        .collect()
}

/// The daemon waits for dind's certificates and endpoint; this waits for
/// dockerd to answer the docker CLI on it.
fn wait_docker(status: &Value, timeout: Duration) -> Result<()> {
    let Some(docker) = docker_cli() else {
        return Ok(());
    };
    let deadline = Instant::now() + timeout;
    loop {
        let ok = Command::new(&docker)
            .args(["version", "--format", "{{.Server.Version}}"])
            .envs(env_of(status))
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if ok {
            return Ok(());
        }
        if Instant::now() > deadline {
            bail!("engine did not become ready in time; see veynodevm logs {NAME}")
        }
        std::thread::sleep(Duration::from_millis(500));
    }
}

/// Create or refresh the `veynodevm` docker context (additive; never switches
/// the current context).
fn ensure_context(status: &Value) -> Result<Option<String>> {
    let Some(docker) = docker_cli() else {
        return Ok(None);
    };
    let certs = PathBuf::from(status["certs"].as_str().unwrap_or_default());
    let endpoint = format!(
        "host=tcp://127.0.0.1:{},ca={},cert={},key={}",
        status["port"],
        certs.join("ca.pem").display(),
        certs.join("cert.pem").display(),
        certs.join("key.pem").display()
    );
    let exists = Command::new(&docker)
        .args(["context", "inspect", CONTEXT])
        .output()?
        .status
        .success();
    let action = if exists { "update" } else { "create" };
    let output = Command::new(&docker)
        .args([
            "context",
            action,
            CONTEXT,
            "--description",
            "VeynodeVM shared engine",
            "--docker",
            &endpoint,
        ])
        .output()?;
    if !output.status.success() {
        bail!(
            "docker context {action} failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        )
    }
    Ok(Some(CONTEXT.into()))
}

/// A host directory shared into the engine at the same path.
fn shared_dir(dir: &str) -> Result<PathBuf> {
    let path = std::fs::canonicalize(dir).with_context(|| format!("--share {dir}"))?;
    if !path.is_dir() || path == std::path::Path::new("/") {
        bail!("--share needs an existing directory other than /: {dir}")
    }
    if path
        .to_str()
        .is_none_or(|p| p.contains(':') || p.contains(','))
    {
        bail!("--share path must be UTF-8 without ':' or ','")
    }
    Ok(path)
}

fn start(rest: &[String]) -> Result<i32> {
    let p = crate::args::parse(
        rest,
        &[
            ("gpus", None, true),
            ("cpus", None, true),
            ("memory", Some('m'), true),
            ("disk-size", None, true),
            ("port", None, true),
            ("image", None, true),
            ("dns", None, true),
            ("mtu", None, true),
            ("share", None, true),
        ],
        false,
    )?;
    let shares = p
        .values("share")
        .iter()
        .map(|dir| shared_dir(dir))
        .collect::<Result<Vec<_>>>()?;
    let number = |flag: &str| -> Result<Option<u64>> {
        p.value(flag)
            .map(str::parse)
            .transpose()
            .with_context(|| format!("invalid --{flag}"))
    };
    let mut args = json!({
        "shares": shares,
        "gpus": p.value("gpus"),
        "cpus": number("cpus")?,
        "memoryMiB": p.value("memory").map(crate::args::memory_mib).transpose()?,
        "diskGiB": p
            .value("disk-size")
            .map(|d| d.trim_end_matches(['g', 'G']).parse::<u64>())
            .transpose()
            .context("invalid --disk-size")?,
        "port": number("port")?,
        "image": p.value("image"),
        "dns": p.values("dns"),
        "mtu": number("mtu")?,
    });
    // Unset options take the daemon's defaults.
    if let Some(args) = args.as_object_mut() {
        args.retain(|_, v| !v.is_null());
    }
    let status = api_stream("engine.start", args, false)?;
    wait_docker(&status, Duration::from_secs(180))?;
    match ensure_context(&status)? {
        Some(context) => println!("engine ready: docker --context {context} ps"),
        None => println!(
            "engine ready at {} (docker CLI not found; see veynodevm engine env)",
            status["endpoint"].as_str().unwrap_or_default()
        ),
    }
    Ok(0)
}

pub fn command(rest: &[String], json_output: bool) -> Result<i32> {
    let action = rest.first().map(String::as_str).unwrap_or("status");
    let tail = rest.get(1..).unwrap_or(&[]);
    match action {
        "start" => start(tail),
        "stop" => {
            api_call("engine.stop", json!({}))?;
            println!("engine stopped");
            Ok(0)
        }
        "rm" => {
            api_call("engine.rm", json!({"force":tail.iter().any(|a| a == "-f")}))?;
            println!(
                "engine removed (images and containers inside it are gone; certificates kept)"
            );
            Ok(0)
        }
        "env" => {
            for (k, v) in env()? {
                println!("export {k}={}", shell_quote(&v));
            }
            Ok(0)
        }
        "status" => {
            let status = match api_call("engine.status", json!({})) {
                Ok(status) => status,
                Err(e) if veynodevm_api::code_of(&e) == veynodevm_api::ErrorCode::NotFound => {
                    println!("engine not created (veynodevm engine start)");
                    return Ok(1);
                }
                Err(e) => return Err(e),
            };
            if json_output {
                println!(
                    "{}",
                    json!({"state":status["state"],"status":status["status"],"endpoint":status["endpoint"],"context":CONTEXT,"gpu":status["gpu"],"backend":status["backend"]})
                );
            } else {
                println!(
                    "{}  endpoint {}  backend {}  gpu {}",
                    status["status"].as_str().unwrap_or_default(),
                    status["endpoint"].as_str().unwrap_or_default(),
                    status["backend"].as_str().unwrap_or_default(),
                    status["gpu"].as_str().unwrap_or("none")
                );
            }
            Ok(0)
        }
        other => bail!("unknown engine command: {other} (start, stop, status, env, rm)"),
    }
}

fn shell_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

/// `veynodevm run --shared ...` → `docker run ...` against the engine, with
/// `--gpus` mapped to the engine's CDI device. `spec` is the run flag table,
/// used to tell option values from the image name.
pub fn run_shared(rest: &[String], spec: &[(&str, Option<char>, bool)]) -> Result<i32> {
    let docker = docker_cli().context("--shared needs the docker CLI on PATH")?;
    let args = shared_args(rest, spec);
    let status = Command::new(docker).args(&args).envs(env()?).status()?;
    Ok(status.code().unwrap_or(125))
}

fn shared_args(rest: &[String], spec: &[(&str, Option<char>, bool)]) -> Vec<String> {
    let takes_value = |arg: &str| -> bool {
        if let Some(long) = arg.strip_prefix("--") {
            return !long.contains('=') && spec.iter().any(|(l, _, t)| *l == long && *t);
        }
        // Short group: a value-taking flag last with nothing after it.
        arg.strip_prefix('-')
            .and_then(|g| g.chars().last())
            .is_some_and(|c| spec.iter().any(|(_, s, t)| *s == Some(c) && *t))
            && arg.len() == 2
    };
    let mut args = vec!["run".to_owned()];
    let mut index = 0;
    while index < rest.len() {
        let arg = &rest[index];
        index += 1;
        if !arg.starts_with('-') || arg == "--" {
            args.extend(rest[index - 1..].iter().cloned());
            break;
        }
        if arg == "--shared" {
            continue;
        }
        if arg == "--gpus" || arg.starts_with("--gpus=") {
            if arg == "--gpus" {
                index += 1;
            }
            args.extend(["--device".into(), "veynodevm.dev/gpu=all".into()]);
            continue;
        }
        args.push(arg.clone());
        if takes_value(arg) && index < rest.len() {
            args.push(rest[index].clone());
            index += 1;
        }
    }
    args
}

/// `veynodevm build -t TAG [--file F] CONTEXT`: build with the engine's
/// BuildKit-capable dockerd, then import the result into the micro-VM image
/// store (`docker save` archive), so it runs with `veynodevm run`.
pub fn build(rest: &[String]) -> Result<i32> {
    let p = crate::args::parse(
        rest,
        &[
            ("tag", Some('t'), true),
            ("file", Some('f'), true),
            ("build-arg", None, true),
        ],
        false,
    )?;
    let tag = p.value("tag").context("build requires -t TAG")?;
    let context = p
        .positional
        .first()
        .context("build requires a CONTEXT directory")?;
    let docker = docker_cli().context("build needs the docker CLI on PATH")?;
    let env = env()?;
    let mut args = vec!["build".to_owned(), "-t".into(), tag.into()];
    if let Some(file) = p.value("file") {
        args.extend(["-f".into(), file.into()]);
    }
    for arg in p.values("build-arg") {
        args.extend(["--build-arg".into(), arg.clone()]);
    }
    args.push(context.clone());
    if !Command::new(&docker)
        .args(&args)
        .envs(env.clone())
        .status()?
        .success()
    {
        bail!("docker build failed")
    }
    let dir = tempdir()?;
    let archive = dir.join("image.tar");
    let saved = Command::new(&docker)
        .args(["save", "-o"])
        .arg(&archive)
        .arg(tag)
        .envs(env)
        .status()?;
    let loaded = if saved.success() {
        api_stream("image.load", json!({"path":archive,"rootfs":true}), false)
    } else {
        Err(anyhow::anyhow!("docker save failed"))
    };
    let _ = std::fs::remove_dir_all(&dir);
    for image in loaded?.as_array().into_iter().flatten() {
        println!(
            "Loaded image: {} ({})",
            image["reference"].as_str().unwrap_or_default(),
            image["rootfs"].as_str().unwrap_or_default()
        );
    }
    Ok(0)
}

/// A private directory for the build's archive, which the daemon reads.
fn tempdir() -> Result<PathBuf> {
    use std::os::unix::fs::DirBuilderExt;
    let dir = std::env::temp_dir().join(format!("veynodevm-build-{}", crate::random_hex(8)));
    std::fs::DirBuilder::new().mode(0o700).create(&dir)?;
    Ok(dir)
}

#[cfg(test)]
mod tests {
    #[test]
    fn shared_translation() {
        let spec: &[(&str, Option<char>, bool)] = &[
            ("publish", Some('p'), true),
            ("gpus", None, true),
            ("shared", None, false),
            ("rm", None, false),
        ];
        let s = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(
            super::shared_args(
                &s(&["--shared", "-p", "8080:80", "--gpus", "all", "--rm", "nginx", "--gpus"]),
                spec
            ),
            s(&[
                "run",
                "-p",
                "8080:80",
                "--device",
                "veynodevm.dev/gpu=all",
                "--rm",
                "nginx",
                "--gpus"
            ])
        );
    }
}
